import React from "react";

function MsgHeading({ title, para }) {
  return (
    <div className=" flex  relative">
      <div className=" flex justify-center">
        <div className=" text-yellow-400 text-xl bg-slate-400">{title}</div>
      </div>
      <p className="">{para}</p>
    </div>
  );
}

export default MsgHeading;
